}

/* Contenitore principale */
.masthead_menu_container {
  background: #1e1e2f !important;
  color: #f5f5f5 !important;
  border-radius: 10px !important;
  max-width: 320px;
  overflow-y: auto;
}

/* Header */
.masthead_menu_header {
  background: #2a2b3d !important;
  padding: 10px !important;
  border-radius: 10px !important;
}

/* Menu utente */
.masthead_usermenu {
  background: #2a2b3d !important;
  padding: 8px !important;
  border-radius: 20px !important;
  margin-top: 10px !important;
  color: #e1e1e1 !important;
    border-left: 8px solid #b0b0b0;
  border-bottom: 8px solid #b0b0b0
}

.masthead_usermenu img{
  border-radius: 8px !important;
}

.masthead_usermenu_menu a{
    color: #e1e1e1 !important
}

/* Voci del menu principale */
.masthead_menu_body ul > li > a {
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;
  color: #ddd !important;
  background: #1e1e2f !important;
  text-decoration: none !important;
  padding: 10px 12px !important;
  border-radius: 6px !important;
  transition: background 0.2s ease-in-out;
  border-bottom: 1px solid rgba(255,255,255,0.1) !important;
}
.masthead_menu_body ul > li > a:hover {
  background: #3b3d55 !important;
  color: #fff !important;
}

/* Submenu */
.masthead_menu_body ul ul {
  margin-left: 10px !important;
  border-left: 2px solid #3b3d55 !important;
  background: #252638 !important;
  border-radius: 6px !important;
}
.masthead_menu_body ul ul a {
  font-size: 0.9em !important;
  padding: 8px 10px !important;
  color: #ccc !important;
}
.masthead_menu_body ul ul a:hover {
  background: #444a66 !important;
  color: #fff !important;
}

/* Icone */
.masthead_menu_body i {
  color: #aaa !important;
}

/* Rimuove la barra rossa a sinistra */
.masthead_menu_body ul {
  border-left: none !important;
}

/* Elimina il bordo/grigio attorno agli elementi */
.masthead_menu_body li {
  background: none !important;
  border: none !important;
}

/* Voci di menu dark uniformi */
.masthead_menu_body ul > li > a {
  background: #2a2b3d !important;
  color: #f5f5f5 !important;
  border-radius: 8px !important;
  margin: 6px 0 !important;
  box-shadow: none !important;
}

/* Hover */
.masthead_menu_body ul > li > a:hover {
  background: #3b3d55 !important;
  color: #ffffff !important;
}

/* Icone freccia (fa-chevron) chiare */
.masthead_menu_body i.fa-chevron-left,
.masthead_menu_body i.fa-chevron-right {
  color: #f5f5f5 !important;
}

/* Submenu */
.masthead_menu_body ul ul {
  background: #232435 !important;
  border-left: 2px solid #3b3d55 !important;
  padding-left: 5px !important;
  border-radius: 6px !important;
}
.masthead_menu_body ul ul a {
  background: transparent !important;
  color: #ccc !important;
}
.masthead_menu_body ul ul a:hover {
  background: #3b3d55 !important;
  color: #fff !important;
}






















.app-box_dati_esito_voto {
  background-color: #25272b !important 
}

dd {
  background-color: #222 !important;
