}

dt {
  background-color: #222 !important;
  color: #e1e1e1 !important;
  border-radius: 10px 0px 0px 10px  !important;
    border-left: 1px solid #413d82;
}

#boxMedie ul {
    background-color: #222 !important;
  color: #e1e1e1 !important;
  border-radius: 10px !important;
}

h1, h2 {
    color: #e1e1e1 !important;
}







/* Contenitore tabella */
table {
  width: 100% !important;
  border-collapse: collapse !important;
  background-color: #1e1e2f !important; /* sfondo dark */
  color: #e0e0e0 !important;
  font-family: "Segoe UI", Roboto, Arial, sans-serif !important;
  border-radius: 12px !important;
  overflow: hidden !important;
  box-shadow: none !important; /* tolta ombra */
}

table img {
  border-radius: 6px
}

/* Header */
table thead,
table thead tr,
table thead th {
  background-color: #27293d !important; /* sfondo header forzato */
  color: #f1f1f1 !important;
  border-bottom: 2px solid #2e2e42 !important;
  padding: 14px 12px !important;
  text-align: left !important;
  font-weight: 600 !important;
  font-size: 14px !important;
  letter-spacing: 0.5px !important;
}

/* Celle */
table td {
  padding: 12px 10px !important;
  font-size: 14px !important;
  border-bottom: 1px solid #2e2e42 !important;
  background-color: #1e1e2f !important;
  color: #e0e0e0 !important;
}

table th {
  padding: 12px 10px !important;
  font-size: 14px !important;
  border-bottom: 1px solid #2e2e42 !important;
  background-color: #1e1e2f !important;
  color: #e0e0e0 !important;
}

/* Link */
table a {
  color: #00e0ff !important;
  text-decoration: none !important;
}

/* Icone */
table img {
  filter: brightness(0.9) contrast(1.1) !important;
}

/* Paginazione e filtri */
.footable-pagination,
.footable-filtering {
  background-color: #1e1e2f !important;
  color: #d1d1d1 !important;
  padding: 10px !important;
  border-top: 1px solid #2e2e42 !important;
}

.footable-pagination a,
.footable-filtering input,
.footable-filtering select {
  background: #2b2d42 !important;
  border: none !important;
  border-radius: 6px !important;
  color: #e0e0e0 !important;
  padding: 6px 10px !important;
  margin: 0 4px !important;
}


#esse3 .table-1 td {
    margin: 0;
    padding: 5px;
   border: none !important;
  border-left: 1px solid #2e2e42 !important;
}

#esse3 .table-1 tr {
    margin: 0;
    padding: 5px;
   border: 1px solid #2e2e42 !important
}

#esse3 .table-1 th {
  border-left: 1px solid #4a4a6a;
}















/* Contenitore filtro */
.form-inline,
.footable-filtering-search {
  background-color: #1e1e2f !important;
  color: #e0e0e0 !important;
  border: none !important;
  border-radius: 8px !important;
}

/* Input di ricerca */
.footable-filtering-search input.form-control {
  background-color: #2b2d42 !important;
  border: 1px solid #2e2e42 !important;
  color: #e0e0e0 !important;
  border-radius: 10px !important;
  box-shadow: none !important;
  
}

.footable-filtering-search input.form-control::placeholder {
  color: #9baacf !important;
}

/* Pulsanti */
.footable-filtering-search .btn {
  border: none !important;
  border-radius: 10px !important;
  padding: 6px 12px !important;
}

.footable-filtering-search .btn-primary {
  background-color: #3a82f7 !important;
  color: #fff !important;
}

.footable-filtering-search .btn-default,
.footable-filtering-search .dropdown-toggle {
  background-color: #2b2d42 !important;
  color: #e0e0e0 !important;
}

/* Icone */
.footable-filtering-search .fooicon {
  color: #fff !important;
}

/* Dropdown menu */
.footable-filtering-search .dropdown-menu {
  background-color: #27293d !important;
  border: 1px solid #2e2e42 !important;
  border-radius: 6px !important;
}

.footable-filtering-search .dropdown-menu li a,
.footable-filtering-search .dropdown-menu li label {
  color: #e0e0e0 !important;
  background: none !important;
}

.footable-filtering-search .dropdown-header {
  color: #9baacf !important;
  font-size: 13px !important;
}

.footable-filtering-search .dropdown-menu input[type="checkbox"] {
  accent-color: #3a82f7 !important; /* colore checkbox moderno */
}


.footable-filtering-search .btn-primary {
    background-color: #1b3968 !important;
    color: #e1e1c2 !important;
}

th.footable-first-visible {
  border-radius: 10px 0 0 0 !important;
}

th.footable-last-visible {
    border-radius: 0 10px 0 0 !important;
}

caption {
  color: #e1e1e1
}








/* Stile per browser basati su WebKit (Chrome, Edge, Safari) */
::-webkit-scrollbar {
  width: 8px !important;   /* larghezza verticale */
  height: 8px !important;  /* altezza orizzontale */
}

::-webkit-scrollbar-track {
  background: #1e1e2f !important; /* sfondo track */
}

::-webkit-scrollbar-thumb {
  background-color: #3b3d55 !important; /* barra scura */
  border-radius: 10px !important;
}

::-webkit-scrollbar-thumb:hover {
  background-color: #4a4d6a !important; /* leggermente più chiaro in hover */
}

/* Firefox */
* {
  scrollbar-width: thin !important;       /* sottile */
  scrollbar-color: #3b3d55 #1e1e2f !important; /* thumb / track */
}



